function flowImage(kind){
 const prepared=run.inference.prepared,source=kind==='white'?run.data.observations.white:run.data.observations.uv;
 const pixels=new Uint8ClampedArray(source.pixels),mask=run.inference.masks[method];
 for(let i=0;i<prepared.roi.length;i++){
  if(kind==='white'&&edge(prepared.roi,i,prepared.width))pixels.set([180,147,81,255],i*4);
  if(kind==='mask'&&mask[i]){
   for(let c=0;c<3;c++)pixels[i*4+c]=Math.round(.63*pixels[i*4+c]+.37*[184,36,42][c]);
   if(edge(mask,i,prepared.width))pixels.set([235,176,106,255],i*4);
  }
 }
 const canvas=host.ownerDocument.createElement('canvas');
 image(canvas,pixels);
 return canvas.toDataURL('image/png');
}
function flowFigure(kind,caption){
 return '<figure style="margin:8px 0;flex:0 1 200px;min-width:140px;max-width:200px"><img src="'+flowImage(kind)+'" alt="'+esc(caption)+'" style="display:block;width:100%;height:auto;border:1px solid #ddd5ca;border-radius:10px"><figcaption>'+esc(caption)+'</figcaption></figure>';
}
function flowComparison(){
 const rows=Object.entries(run.inference.summaries);
 const chart=rows.map(([key,v],i)=>{
  const y=12+i*38,width=240*Math.max(0,Math.min(1,v.area??0));
  return '<text x="5" y="'+(y+17)+'" font-size="16" fill="#343941">'+esc(methodNames[key])+'</text><rect x="150" y="'+y+'" width="240" height="22" rx="4" fill="#eee8e0"/><rect x="150" y="'+y+'" width="'+width.toFixed(2)+'" height="22" rx="4" fill="'+(key===method?'#b8242a':'#718391')+'"/><text x="405" y="'+(y+17)+'" font-size="15" fill="#343941">'+pct(v.area)+' · '+v.count.toLocaleString()+' / '+v.denominator.toLocaleString()+' 像素</text>';
 }).join('');
 return '<div style="overflow-x:auto"><svg viewBox="0 0 680 140" role="img" aria-label="三种方法的显示面积比例，条长使用同一百分比尺度，并列出共同分母" style="display:block;width:100%;min-width:560px;max-width:680px;height:auto">'+chart+'<text x="150" y="137" font-size="14" fill="#62636a">0%</text><text x="390" y="137" text-anchor="end" font-size="14" fill="#62636a">100%</text></svg></div>';
}
function contributionChart(calc){
 const limit=Math.max(.001,...calc.contributions.map(v=>Math.abs(v))), width=150;
 const bars=calc.contributions.map((value,i)=>{const y=12+i*36,w=Math.abs(value)/limit*width,x=value<0?260-w:260;return '<text x="2" y="'+(y+16)+'" font-size="14" fill="#343941">'+esc(calc.names[i])+'</text><rect x="'+x.toFixed(2)+'" y="'+y+'" width="'+w.toFixed(2)+'" height="20" fill="'+(value<0?'#718391':'#b8242a')+'"/><text x="425" y="'+(y+16)+'" font-size="14" fill="#343941">'+(value>=0?'+':'')+fmt(value,3)+'</text>';}).join('');
 return '<div style="overflow-x:auto"><svg viewBox="0 0 510 205" role="img" aria-label="当前像素的五项逻辑回归特征对模型得分的正负贡献" style="width:100%;min-width:430px;max-width:510px"><path d="M260 8V190" stroke="#62636a"/>'+bars+'<text x="110" y="204" font-size="13" fill="#62636a">降低得分 ←　0　→ 提高得分</text></svg></div>';
}
