function fieldsHTML(f){if(!f)return '<p>没有字段。</p>';const a=f.fields;return `<dl class="wb-fields"><div><dt>井段 / m MD</dt><dd>${esc(a.depthRangeMD_m?.join('—')||'原文未提供')}</dd></div><div><dt>数值与单位</dt><dd>${a.gasValue!=null?fmt(a.gasValue,1)+' '+esc(a.gasUnit||'单位未提供'):esc(a.rock||a.fluorescence||a.operation||'本句无该项')}</dd></div><div><dt>肯定／否定</dt><dd>${a.negation===true?'未见／未检出':a.negation===false?'按原文保留':'需核对表达'}</dd></div></dl>`;}
