 if(scene==='m4'){const p=selected(scene,run,state);if(!p.norm.valid)return '';body=table(['工况项','当前对数比','标定系数','当前贡献'],p.norm.x?g.M4Core.predictors(p.row).map((v,j)=>[['基础项','log(钻压/20)','log(转速/120)','log(排量/0.025)'][j],fmt(v,4),fmt(run.library.cal.beta[j],4),fmt(v*run.library.cal.beta[j],4)]):[])+`<p>工况估计 log ROP ${fmt(p.norm.predictedLogROP,4)}；实际 log ROP ${fmt(Math.log(p.row.ROP_m_h),4)}。本轮实际减去 ${fmt(run.config.normalize?p.norm.predictedLogROP:run.library.cal.beta[0],4)}（${run.config.normalize?'完整工况估计':'仅基础项'}），用于分组的钻速响应 ${fmt(p.norm.normalized,4)}。</p>`;const m=run.library.models[run.config.k],z=g.S17Math.scale(p.norm.x,m.scaler);body+=table(['响应组','标准化中心1','标准化中心2','当前至中心距离'],m.centers.map((c,j)=>['组'+String.fromCharCode(65+j),fmt(c[0],4),fmt(c[1],4),fmt(Math.sqrt(z.reduce((sum,v,k)=>sum+(v-c[k])**2,0)),4)]))+`<p>当前点两项响应先按训练均值 ${m.scaler.mu.map(v=>fmt(v,4)).join(' / ')} 与标准差 ${m.scaler.sd.map(v=>fmt(v,4)).join(' / ')} 缩放。连续分段进一步考虑切换代价 ${run.config.penalty} 和最小段长 ${run.config.minLength}。</p>`;}
 if(scene==='m5'){const f=selected(scene,run,state);if(!f)return '';const m=run.library.model,rank=f.prediction.scores.map((v,i)=>[v,i]).sort((a,b)=>b[0]-a[0]),a=rank[0][1],b=rank[1][1],vs=new Set(m.vocabulary),freq={};for(const t of g.M5Core.tokens(f.rawQuote))if(vs.has(t))freq[t]=(freq[t]||0)+1;const logp=(c,t)=>Math.log(((m.counts[c][t]||0)+m.alpha)/(m.totals[c]+m.alpha*vs.size));body=table(['词项','次数',g.M5Core.labels[a]+' log P',g.M5Core.labels[b]+' log P','对分差贡献'],Object.entries(freq).map(([t,n])=>[t,n,fmt(logp(a,t),4),fmt(logp(b,t),4),fmt(n*(logp(a,t)-logp(b,t)),4)]))+`<p>类别分数还包含先验。当前最高类${g.M5Core.labels[a]}比${g.M5Core.labels[b]}高 ${fmt(f.prediction.scores[a]-f.prediction.scores[b],4)} 对数分。数字只在分类词项中替换为“数”，原文和事实字段保持原值。</p>`;}
