function trace(run,s={}){if(!run)return null;const p=V.selected('m2',run,s);if(!p)return null;const model=run.library.model,neighbors=p.prediction.neighbors.map(n=>({...n,weight:1/Math.max(.05,n.distance),group:model.samples[n.index].group})),total=neighbors.reduce((v,n)=>v+n.weight,0),chosen=neighbors[Math.min(s.neighbor||0,neighbors.length-1)],reference=model.samples[chosen.index],features=p.features.x.map((value,j)=>({name:titles[j],value,reference:reference.x[j],mean:model.mu[j],sd:model.sd[j],squaredDifference:((value-reference.x[j])/model.sd[j])**2}));return {time:p.event.time_s,dimensions:p.features.x.length,k:run.config.k,neighbors,totalWeight:total,votes:p.prediction.votes,support:p.prediction.support,proposedLabel:p.prediction.proposedLabel,label:p.prediction.label,reasons:p.prediction.reason,chosenNeighbor:Math.min(s.neighbor||0,neighbors.length-1),distanceSquaredMean:features.reduce((v,f)=>v+f.squaredDifference,0)/features.length,features};}
function explain(run,s={}){const t=trace(run,s);if(!t)return '<p class="wb-empty">'+(run.inference.length?'原选中气峰暂未检出，其他气峰仍在。可调整阈值恢复原峰，或从左侧选择另一个气峰。':'当前阈值下没有检出气峰。调低检测阈值，可以继续看实际近邻投票。')+'</p>';const n=t.neighbors[t.chosenNeighbor],features=[...t.features].sort((a,b)=>b.squaredDifference-a.squaredDifference),top=features.slice(0,4),rest=features.slice(4).reduce((a,b)=>a+b.squaredDifference,0),steps=['描述这个峰','寻找相似事件','按距离投票','形成解释'],notes=[`当前峰用${t.dimensions}个数描述。峰形、组分${run.config.context?'及来源工况':'信息'}一起进入比较，先按参考库的均值与标准差统一尺度。`,`右侧展开第${t.chosenNeighbor+1}个近邻的实际距离。条形越长，表示这一项越拉大两个事件的差异。距离不是模型学得的特征权重。`,`每个近邻给自己的类别投一票，票重＝1 / max(0.05, 距离)。所有${t.k}个近邻都参与；更近的事件票更重。`,`支持度＝领先类别票重 ÷ 全部票重。随后检查来源能否求解、是否超出参考分布${run.config.context?'、工况是否冲突':''}等条件，决定是否暂缓解释。`];
return `<section class="wb-knn" data-explain-step="${s.explainStep||0}" aria-label="当前气峰的加权kNN计算"><header><span class="wb-eyebrow">打开这一次判断</span><h3>加权 kNN：相似事件怎样投出这个候选？</h3><p>同一个气峰、当前实际的 ${t.k} 个近邻。点一个近邻，看哪些特征让它接近或远离。</p></header><div class="wb-knn-steps" role="group" aria-label="逐步看本轮计算">${steps.map((v,i)=>`<button type="button" data-wb-explain="${i}" aria-pressed="${(s.explainStep||0)===i}">${i+1} ${v}</button>`).join('')}</div><p class="wb-knn-instruction">${notes[s.explainStep||0]}</p><div class="wb-knn-network"><article class="wb-knn-input" data-knn-column="0"><small>当前输入</small><h4>峰 ${String.fromCharCode(65+(s.selected||0))}</h4><b>${t.dimensions} 维特征</b><p>峰高 ${fmt(t.features[0].value)}<br>峰宽 ${fmt(t.features[1].value,0)} s<br>组分比 ${fmt(t.features[5].value,3)}</p><span>${run.config.context?'气测＋来源工况':'仅气测形状与组分'}</span></article><div class="wb-knn-neighbors" data-knn-column="1"><small>实际参考事件 · 距离越小，票越重</small>${t.neighbors.map((a,i)=>`<button type="button" data-wb-neighbor="${i}" aria-pressed="${t.chosenNeighbor===i}" style="--vote:${a.weight/t.totalWeight*100}%"><span class="wb-knn-node">${i+1}</span><span><b>${esc(V.names.m2[a.label])}</b><small>${esc(a.group)} · 距离 ${fmt(a.distance,3)}</small></span><strong>${fmt(a.weight,3)}<small>票重</small></strong></button>`).join('')}</div><article class="wb-knn-votes" data-knn-column="2"><small>类别票重汇总</small>${V.bars(t.votes.map((v,i)=>({name:V.names.m2[i],value:v,color:i===t.proposedLabel?V.palette[0]:V.palette[1]})),{label:'当前气峰实际类别票重'})}<p>${fmt(t.votes[t.proposedLabel],3)} ÷ ${fmt(t.totalWeight,3)}<br><b>支持度 ${pct(t.support)}</b></p></article></div><div class="wb-knn-final" data-knn-column="3"><span>投票候选：${esc(V.names.m2[t.proposedLabel])}</span><strong>当前输出：${esc(V.names.m2[t.label])}</strong><p>${t.reasons.length?'暂缓原因：'+esc(t.reasons.join('；')):(run.config.context?'当前来源、工况与分布检查未触发暂缓；下一步按同一来源井段核对其他录井资料。':'当前仅比较气测特征，未使用来源工况；来源与分布检查未触发暂缓，后续仍需补充工况资料。')}</p></div><details class="wb-knn-distance" ${s.explainStep===1?'open':''}><summary>第${t.chosenNeighbor+1}个近邻：距离由哪些特征构成？</summary>${V.bars(top.map(f=>({name:f.name,value:f.squaredDifference,color:V.palette[1]})).concat([{name:'其余 '+(t.dimensions-top.length)+' 项合计',value:rest,color:V.palette[2]}]),{label:'当前与所选近邻的标准化差值平方；各项相加用于距离'})}<p>每项＝((当前值 − 近邻值) ÷ 参考库标准差)²。距离＝√(各项之和 ÷ ${t.dimensions})＝${fmt(Math.sqrt(t.distanceSquaredMean),4)}；票重＝1 / max(0.05, ${fmt(n.distance,4)})＝${fmt(n.weight,4)}。</p>${V.table(['特征','当前值','近邻值','参考库标准差','标准化差值²'],t.features.map(f=>[f.name,fmt(f.value,4),fmt(f.reference,4),fmt(f.sd,4),fmt(f.squaredDifference,4)]))}</details><details><summary>同一气测，补充工况前后有什么不同？</summary>${V.m2Candidates(run,s)}</details></section>`;
}
V.m2Trace=trace;V.m2Explain=explain;
