 function dataPreview(data,computed=false){const o=data.observations;if(scene==='m1'||scene==='m3')return `<div class="wb-pair">${V.image('white','白光 · '+esc(o.identity.parentSampleId))}${scene==='m3'?V.image('uv','UV · 同一配对号 '+esc(o.identity.capturePairId)):`<div class="wb-preview-copy"><b>同一图里的参照片</b><p>左上角参考片与岩屑一起拍摄，用它对齐颜色尺度。</p><p>图像320×240像素；模型${computed?'已':'尚未'}执行。</p><span class="wb-data-tag">${esc(o.identity.capturePairId)}</span></div>`}</div>`;if(scene==='m2')return V.gasChart({observations:o,inference:[]},{...s,selected:null},'gas');if(scene==='m4')return `<div class="wb-data-table"><table><caption>${o.rows.length}条记录 · 前6行原始观测</caption><thead><tr><th>MD / m</th><th>ROP / m·h⁻¹</th><th>WOB / kN</th><th>RPM</th><th>有效</th></tr></thead><tbody>${o.rows.slice(0,6).map(r=>`<tr><td>${fmt(r.depthMD_m)}</td><td>${fmt(r.ROP_m_h)}</td><td>${fmt(r.WOB_kN,1)}</td><td>${fmt(r.RPM,0)}</td><td>${r.active?'是':'停钻'}</td></tr>`).join('')}</tbody></table></div>`;return `<pre class="wb-raw-preview">${esc(o.rawText)}</pre>`;}
