 function summary(){const r=s.run;if(!r)return null;if(scene==='m1')return{count:g.M1Core.proportions(r.inference.results,'model','count'),area:g.M1Core.proportions(r.inference.results),selected:s.selected,anchor:s.anchor?{x:s.anchor.x,y:s.anchor.y}:null};if(scene==='m2')return{events:r.inference.length,selected:s.selected,candidate:V.selected(scene,r,s)?.prediction,source:V.selected(scene,r,s)?.features.sourceTime_s,gasSignature:r.gasSignature};if(scene==='m3')return{methods:D.plain(r.inference.summaries),selectedPoint:s.point,method:s.method,saturated:r.inference.prepared.saturated};if(scene==='m4')return{boundaries:r.inference.boundaries,baseline:r.inference.baseline,depth:s.depth,validRows:r.inference.validCount};return{clauses:r.inference.clauses.length,claims:r.inference.claims.map(c=>({statement:c.statement,reviewStatus:c.reviewStatus})),facts:r.inference.facts};}
