 function snapshot(){return{...legacySnapshot(),status:s.status,layout:'continuous',automaticAnalysis:true,algorithm:V.what[scene][0],explanationObject:scene==='m2'?V.m2Trace(s.run,s):null,experimentPhase:s.phase,dataSource:s.loaded?.origin||null,dataLoaded:!!s.loaded,inputFingerprint:s.run?.inputFingerprint||s.loaded&&D.inputFingerprint(scene,s.loaded.observations),processingComplete:ready(),revision:s.revision,runId:s.run?.runId,selected:scene==='m3'?s.point:scene==='m4'&&s.run?V.selected(scene,s.run,s).index:s.selected,stage:s.view==='how'?1:0,anchor:s.anchor?{x:s.anchor.x,y:s.anchor.y,pixel:s.anchor.y*320+s.anchor.x,originalBBox:s.anchor.bbox||null,selectionRevision:s.anchor.selectionRevision||1,arrangement:s.settings.preset}:null,point:s.point,settings:s.run?.config||s.settings,metrics:s.run?.metrics,results:scene==='m2'?s.run?.inference:undefined,gasSignature:s.run?.gasSignature,trainCount:s.run?.library.trainCount,validCount:s.run?.library.validCount,reviews:s.reviews,summary:summary()};}
 function download(file){const url=URL.createObjectURL(new Blob([file.text],{type:file.type})),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function action(name){if(name==='load')setLoaded(sample());if(name==='sample')download(D.sampleFile(scene,preview()));if(name==='run')recalculate();if(name==='reset'){clearTimeout(timer);s.pending++;s.settings=D.defaults(scene);s.depth=1240;s.method='M0';s.neighbor=0;s.explainStep=0;setLoaded(sample());}if(name==='data'){host.querySelector('.wb-input-details').open=true;}if(name==='result'&&ready()){s.phase='result';render();}if(name==='save'){try{const e=evidence();download({name:D.ids[scene]+'-'+e.runId+'.json',type:'application/json;charset=utf-8',text:JSON.stringify(e,null,2)});s.notice='已保存本次输入与计算结果。';render();}catch(e){s.error=e.message;render();}}if(name==='confirm'&&ready()){const c=s.run.inference.claims[s.selected];c.reviewStatus='confirmed';c.reviewHistory.push({revision:s.revision,trigger:'读者逐句核对',reviewStatus:'confirmed'});s.reviews.push({claimId:c.claimId,revision:s.revision,statement:c.statement,reviewStatus:'confirmed'});s.notice='已核对当前修订的句子。';render();}if(['negation','value','range'].includes(name)&&scene==='m5'){let raw=s.loaded.observations.rawText;if(name==='negation')raw=raw.includes('未见明显荧光')?raw.replace('未见明显荧光','见明显荧光'):raw.replace('见明显荧光','未见明显荧光');if(name==='value')raw=raw.includes('3.2')?raw.replace('3.2','5.1'):raw.replace('5.1','3.2');if(name==='range')raw=raw.includes('1220—1230')?raw.replace('1220—1230','1222—1232'):raw.replace('1222—1232','1220—1230');s.loaded={...s.loaded,origin:'edited',isBuiltin:false,observations:{rawText:raw}};schedule();}}
